Lemma file_read_firstn : forall data len count, 0 <= len < 2^64 -> 0 <= count < 2^64 ->
  file_read data (Z_to_bv 64 len) (Z_to_bv 64 count) = firstn (Z.to_nat count) (skipn (Z.to_nat len) data).
Proof.
